export const CH24_28_NEW = {
  italus: ["Italus", "Italus, of whom Italie was named after the Colonie of the Eleans. Raleigh denies that he is Atlas, or Cethim.", "him"],
  aetolus: ["Aetolus", "Aetolus, also written Aitolus, sonne of a King of Elis, and founder of the Aetolian Kingdome. Raleigh deriues the name Italus from him.", "him"],
  maia: ["Maia", "Maia, sister of Electra, whom Virgil calleth, poetically, a daughter of the Mountaine Atlas in Africa.", "her"],
  elatus: ["Elatus", "Elatus, a Prince of Arcadia, sonne of Arcas, who founded the Citie Elateia. Reyneccius his conjecture, that Telephus took this name, is reported and not followed.", "him"],
  arcas: ["Arcas", "Arcas, King of Arcadia, father of Aphidas and Elatus, which gaue name to the Countrie.", "him"],
  aphidas: ["Aphidas", "Aphidas, sonne of Arcas, of one of the two Families that succeeded in Arcadia.", "him"],
  hippotheus: ["Hippotheus", "Hippotheus, of the race of Elatus, who held Arcadia at the end of the Troian warre.", "him"],
  echemus: ["Echemus", "Echemus, King of Arcadia, slaine by mischance by his sonne, whose name is a gap. The gap was not filled.", "him"],
  aleus: ["Aleus", "Aleus, King of Arcadia, father of Auge.", "him"],
  auge: ["Auge", "Auge, the Daughter of Aleus, on whom Hercules begat Telephus. She is not Augeas.", "her"],
  oenotrus: ["Oenotrus", "Oenotrus, who planted the people in that part of Italie to which Telephus came. The Oenotri are his people, and were not split.", "him"],
  telephus: ["Telephus", "Telephus, the Sonne of Hercules and Auge, and the father of Eurypylus. Suidas giues this name to the Latinus who was the sonne of Hercules. He is not the brother who conducted the Ceteans.", "him"],
  "eurypylus-son-of-telephus": ["Eurypylus son of Telephus", "Eurypylus, also printed Eurypilus, Lord of the Ceteans, sonne of Telephus, slaine by Achilles. He is not Euripylus the sonne of Mecisteus, and not Euripilus the Greeke commander. The one-word title would fold onto euripylus, so the title is four words.", "him"],
  "telephus-brother-of-eurypylus": ["Telephus brother of Eurypylus", "Telephus, brother of Eurypylus, who conducted the Ceteans into Italie. Reyneccius makes him the nephew of Hercules, by a sonne of the same name. He is not Telephus the father. The one-word title would fold onto telephus, so the title is four words.", "him"],
  sabus: ["Sabus", "Sabus, also called Sabinus, from whom some deriue the Sabines. He is not the Babylonian Sabu.", "him"],
  fauna: ["Fauna", "Fauna, called Fatua, the sister and Wife of Faunus.", "her"],
  marica: ["Marica", "Marica, the Nymph by whom Virgil giues Latinus to Faunus as his Sonne. Her abode was about the Riuer Liris neere Minturnae.", "her"],
  telemathus: ["Telemathus", "Telemathus, father of the fourth man whom Pomponius Sabinus calleth Latinus. The printed spelling is kept.", "him"],
  "latinus-son-of-ulysses": ["Latinus son of Vlysses", "The third Latinus in Pomponius Sabinus his count of foure, the sonne of Vlysses by Circe. He is not Latinus the sonne of Faunus. The one-word title would fold onto latinus, so the title is four words.", "him"],
  "latinus-son-of-telemathus": ["Latinus son of Telemathus", "The fourth Latinus in Pomponius Sabinus his count, the sonne of Telemathus. He is not Latinus the sonne of Faunus. The one-word title would fold onto latinus, so the title is four words.", "him"],
  lauinia: ["Lauinia", "Lauinia, the onely Daughter and Heire of Latinus, promised to Turnus and then giuen to Aeneas.", "her"],
  turnus: ["Turnus", "Turnus, the sonne of Venilia, to whom Latinus promised Lauinia, slaine in the warre that followed.", "him"],
  venilia: ["Venilia", "Venilia, sister to Amata, and mother of Turnus.", "her"],
  amata: ["Amata", "Amata, the Wife of Latinus. Virgil and Halicarnassaeus call her Amata, and Varro calleth her Palatia.", "her"],
  creusa: ["Creusa", "Creusa, the daughter of Priamus, and wife of Aeneas, mother of Ascanius.", "her"],
  "iulus-son-of-ascanius": ["Iulus son of Ascanius", "Iulus, the sonne of Ascanius, who held the Priesthood when the people gaue the Kingdome to Syluius Posthumus. He is not Ascanius, whose surname was also Iulus. The one-word title would fold onto that surname, so the title is four words.", "him"],
  numitor: ["Numitor", "Numitor, also printed Numilor, the elder sonne of Procas, depriued by Amulius, and grandfather of Romulus. The list calls him Syluius Numitor.", "him"],
  aegesthus: ["Aegesthus", "Aegesthus, the sonne of Numitor, slaine by Amulius. He is not a man of the house of Agamemnon.", "him"],
  ilia: ["Ilia", "Ilia, called also Rhea, the daughter of Numitor, and mother of Romulus and Remus. A third name is a gap and was not filled.", "her"],
  antho: ["Antho", "Antho, the daughter of Amulius, at whose entreatie the mother of Romulus may haue beene pardoned.", "her"],
  cluilius: ["Caius Cluilius", "Caius Cluilius, Dictator of Alba, who in the dayes of Tullus Hostilius dyed in the Campe before Rome.", "him"],
  "metius-suffetius": ["Metius Suffetius", "Metius Suffetius, the successor of Cluilius, whom Tullus Hostilius caused to be torne in pieces.", "him"],
  tibris: ["Tibris", "Tibris, of whom Virgil, as Raleigh reads him, gaue the Riuer Tiber its name, before the comming of Aeneas. He is not Tiberinus.", "him"],
  "iulius-father-of-proculus": ["Iulius father of Proculus", "Another Iulius, father of Iulius Proculus, and sonne of the brother of Auentinus. That brother's name is a gap and was not filled. He is not Iulius Caesar. The one-word title would fold onto julius-caesar, so the title is four words.", "him"],
  "iulius-proculus": ["Iulius Proculus", "Iulius Proculus, who leauing Alba, dwelt with Romulus in Rome. He is not Iulius Caesar.", "him"],
  "calphurnius-piso": ["Calphurnius Piso", "Calphurnius Piso, named with Q. Fabius Pictor and Portius Cato among those who deriue the Romans from Ianus.", "him"],
  marsylus: ["Marsylus", "Marsylus, named with Herodotus among those who giue the Graecians for ancestors of the Romans.", "him"],
  caecilius: ["Caecilius", "Caecilius, printed CAECILIVS, a Romane Historiographer, who gathereth that Rome was built by the Greekes, because they sacrifice to Hercules.", "him"],
  romanus: ["Romanus", "Romanus, the sonne of Vlysses and Circe, whom Plutarch remembers among the founders of Rome. He is not Romulus.", "him"],
  emathion: ["Emathion", "Emathion, the father of one Romus, whom Diomedes sent from Troy.", "him"],
  "romus-son-of-emathion": ["Romus son of Emathion", "Romus, the sonne of Emathion, whom Diomedes sent from Troy, in Plutarch his list of the founders of Rome. He is not Remus, and not the Tyrant Romus. The one-word title would be shared, so the title is four words.", "him"],
  "romus-tyrant": ["Romus the Tyrant", "One Romus, a Tyrant of the Latines, who draue the Tuscans out and built Rome, in the same list. He is not Romus the sonne of Emathion, and not Remus.", "him"],
  februa: ["Februa", "Februa, the mother of Mars, after whom some say Rome was anciently called Febris. Mars was not made a person.", "her"],
  faustula: ["Faustula", "Faustula, a Shepheards wife, who tooke Romulus from the Wolfe.", "her"],
  fauchet: ["Fauchet", "Fauchet, whose Antiquitez de Gaule tells that Meroueë was begotten by a Monster of the Sea, and who sayes, let them beleeue it that list.", "him"],
  merouee: ["Meroueë", "Meroueë, King of the Francs, of whom Fauchet rehearses the fable of a Monster of the Sea. The printed spelling is kept.", "him"],
  oenone: ["Oenone", "Oenone, who confessed to Paris that she had beene rauished by Apollo.", "her"],
  anchyses: ["Anchyses", "Anchyses, who boasted that hee had knowne Venus. The printed spelling is kept.", "him"],
  anastasius: ["Anastasius", "Anastasius the Emperour, slaine with lightning.", "him"],
  carus: ["Carus", "Carus the Emperour, who succeeded Probus, and was slaine with lightning whilest he lodged vpon the Riuer Tigris.", "him"],
  probus: ["Probus", "Probus, whom Carus the Emperour succeeded.", "him"],
  vesta: ["Vesta", "Vesta, the Goddesse, whose Nunnes were the Vestall Virgins. Amata, or Palatia, is the name by which the High Priest called euery such Virgin.", "her"],
  tatius: ["Tatius", "Tatius, companion of Romulus in the Kingdome, whose death Romulus did not reuenge.", "him"],
  "erasmus-reinholdus": ["Erasmus Reinholdus", "Erasmus Reinholdus, whose Prutenick Tables are alleaged for the distance betweene Nabonassar and Mardocempadus. He is not Erasmus, who deuised the fable of our Ladies letters.", "him"],
  "bartholomew-scultet": ["Bartholomew Scultet", "Bartholomew Scultet, commended for skill in Astronomie, who by calculation found a day for the Sunnes going backe. Raleigh hath not seene his workes.", "him"],
  lidyate: ["Lidyate", "Lidyate, Raleigh his countrie-man, who reprehended Scaliger for changing his opinion of Mardocempadus.", "him"],
  "william-the-conqueror": ["William the Conqueror", "William the Conqueror, named onely as an example, that neerenesse of time doth not proue a man to be sonne or grand-child. He is not William of Tyre.", "him"],
  "edward-the-confessor": ["Edward the Confessor", "Edward the Confessor, named with William the Conqueror in the same example. He is not King Edward who was in prison with King Richard, and not Prince Edward.", "him"],
  "tobias-son-of-tobie": ["Tobias son of Tobie", "The sonne of Tobias, of the same name, carried with his father and with Anna to Niniue. He is not the father Tobie. The one-word title would fold onto that name, so the title is four words.", "him"],
  "anna-wife-of-tobit": ["Anna wife of Tobie", "Anna, the wife of Tobias, carried with him and with his sonne to Niniue. She is not Anna the mother of Mary, and not Anna the sister of Dido. The one-word title would fold onto those records, so the title is four words.", "her"],
  adramelech: ["Adramelech", "Adramelech, a sonne of Sennacherib, who with Sharezer slew their father in the Temple, and fled into Armenia.", "him"],
  sharezer: ["Sharezer", "Sharezer, also printed Selennar, a sonne of Sennacherib, who with Adramelech slew their father. The two spellings are one man.", "him"],
  nesroch: ["Nesroch", "Nesroch, also called Arasces, the god in whose Temple Sennacherib was slaine. Raleigh sayes it is vncertaine what this Nesroch was.", "him"],
  candaules: ["Candaules", "Candaules, the sonne of Myrsus, the last King of the Heraclidae in Lydia, slaine by Gyges. The race was not split into other men.", "him"],
  cardiceas: ["Cardiceas", "Cardiceas, also printed Gardiceas, King of Media after Medidus. Raleigh sayes these two Kings are found in Eusebius, and he reckons them with Ezekia.", "him"],
  mandanes: ["Mandanes", "Mandanes, in the Median lists of Annius and of Diodorus, who raigned fiftie yeeres after Arbaces. The same name and the same length were left as one man.", "him"],
  sosarmon: ["Sosarmon", "Sosarmon, in Annius his list of the Median Kings, who raigned thirtie yeeres. That list was not equated with Eusebius his Sosarmus.", "him"],
  articarmin: ["Articarmin", "Articarmin, in Annius his Median list, who raigned fiftie yeeres. He was not equated with Artycas.", "him"],
  arbianes: ["Arbianes", "Arbianes, in the Median lists of Annius and of Diodorus, who raigned twentie two yeeres. The same name and the same length were left as one man.", "him"],
  attines: ["Attines", "Attines, in Annius his Median list, who raigned twentie two yeeres. He was not equated with Artynes.", "him"],
  astybarus: ["Astybarus", "Astybarus, in Annius his list, who raigned twentie yeeres with his sonne Apanda. He was not equated with Astybara.", "him"],
  apanda: ["Apanda", "Apanda, the sonne of Astybarus, who raigned with his father and then thirtie yeeres alone. The two mentions are one man.", "him"],
  artycas: ["Artycas", "Artycas, in Diodorus his Median list, who raigned fiftie yeeres. He was not equated with Articarmin.", "him"],
  arfaeus: ["Arfaeus", "Arfaeus, in Diodorus his Median list, who raigned fortie yeeres.", "him"],
  artynes: ["Artynes", "Artynes, in Diodorus his Median list, who raigned twentie two yeeres. He was not equated with Attines.", "him"],
  "artabanus-of-media": ["Artabanus of Media", "Artabanus, in Diodorus his list of the Median Kings, who raigned fortie yeeres. He is not the Egyptian Artabanus of seuen moneths. The one-word title would fold onto artabanus, so the title is three words.", "him"],
  astybara: ["Astybara", "Astybara, in Diodorus his list. The continuance of his raigne is not giuen. He was not equated with Astybarus, nor with Astyages.", "him"],
  aesimedes: ["Aesimedes", "Aesimedes, the second of the foure first Gouernours of Athens chosen for ten yeeres. Of him Raleigh findes only the name.", "him"],
  elidicus: ["Elidicus", "Elidicus, the third of those Gouernours. Of him Raleigh findes only the name.", "him"],
  hippones: ["Hippones", "Hippones, the fourth of those Gouernours, who shut his daughter vp with an Horse. Her name is not printed.", "him"],
  lydus: ["Lydus", "Lydus, the sonne of Atys, who gaue the name of Lydia, if the authoritie he cites be beleeued.", "him"],
  "atys-of-lydia": ["Atys of Lydia", "Atys, the father of Lydus. He is not Syluius Atys. The one-word title would not say which Atys, so the title is three words.", "him"],
  argon: ["Argon", "Argon, on whom an Oracle conferred the Kingdome of Lydia. He came of a sonne of Hercules by Iardana. That sonnes name is a gap and was not filled. Hercules was not attached.", "him"],
  iardana: ["Iardana", "Iardana, a bond-woman, by whom a sonne of Hercules, whose name is a gap, begat the line of Argon. The gap was not filled.", "her"],
  myrsus: ["Myrsus", "Myrsus, the father of Candaules.", "him"],
  dascylus: ["Dascylus", "Dascylus, the father of Gyges.", "him"],
  dargan: ["Dargan", "Dargan, a powerfull and a subtile man, who made himselfe Soldan in Aegypt, chased away Sanar, and was slaine by treason.", "him"],
  noradine: ["Noradine", "Noradine, King of Damasco, who sent an Armie of his Turkes, vnder Syracon, against the Soldan Dargan.", "him"],
  amalricke: ["Amalricke", "Amalricke, also written Almaricke and Almericke, King of Ierusalem, who warred in Aegypt and aided the Soldan Sanar against the Turkes. The three spellings are one man.", "him"],
  "hugh-earl-of-caesarea": ["Hugh Earle of Caesarea", "Hugh Earle of Caesarea, with whom William of Tyre had full discourse of the Caliphs estate. The Earle sent to the Caliph, whose name is a gap, was not filled, and was not equated with this Hugh.", "him"],
  acherres: ["Acherres", "Acherres, the first of the Aegyptian Kings set downe after Chenchres, who perished in the Red Sea. Raleigh doth not affirme that he was Vchoreus.", "him"],
  vchoreus: ["Vchoreus", "Vchoreus, whom Diodorus saith was the eighth from Osymandyas. Mercator takes Ogdous for another name of this man. Raleigh doth not affirme that Acherres was he.", "him"],
  osymandyas: ["Osymandyas", "Osymandyas, a great King, whose monument Diodore describes, with the inscription, I am OSYMANDYAS King of Kings. The coniecture that the tombe might be Iosephs is reported, and this man is kept.", "him"],
  timaus: ["Timaus", "Timaus, whom Reineccius coniectures to haue beene the great Osymandyas. Raleigh finds the distance against that coniecture, and the two names are kept apart.", "him"],
  gehoar: ["Gehoar", "Gehoar, Lieutenant vnto the Caliph Elcain, who built the great Citie of Cairo and named it El Cahira. Raleigh names him as such a King as might haue built Memphis.", "him"],
  elcain: ["Elcain", "Elcain, the Caliph, to whose vse Gehoar conquered Aegypt and built Cairo.", "him"],
  myris: ["Myris", "Myris, also written Meris, who caused the great Lake to be made which beares his name. Reineccius takes Armeus to haue beene this man. Raleigh doth not follow that, and this Myris is not Thermutis.", "him"],
  heliogabalus: ["Heliogabalus", "Heliogabalus, whose vnsuteable conditions made the Roman Successors forbeare the name of Antonini. The Antonini were not split into men.", "him"],
  "iohn-leo": ["Iohn Leo", "Iohn Leo, who writes that the Soldan of Aegypt, after Saladine, had vnder him a Viceroy stiled Eddaguadare. He is not Iohn the Apostle, and not Iohn of Gischala. The one-word title would fold onto john, so the title is two words.", "him"],
  cetes: ["Cetes", "Cetes, another name of the Proteus who tooke Helena from Paris, as he is named by some. Raleigh takes him, with Thon, for an vnder-Officer about Pharos. Proteus is kept on his owne record.", "him"],
  thon: ["Thon", "Thon, named with Proteus or Cetes by Greeke Writers. Raleigh takes him for an vnder-Officer about Pharos.", "him"],
  remphes: ["Remphes", "Remphes, the Sonne of Proteus, whom Herodotus calls Ramsinitus. Raleigh doubts that either this King, or his Father, did raigne at all. The two names are one man. The Daughter and the Theefe are not named.", "him"],
  banchyris: ["Banchyris", "Banchyris, recorded by Suidas for his great justice. Bocchorus may be taken for this man. The two names are kept apart.", "him"],
  thulis: ["Thulis", "Thulis, also called Thules, of whom Suidas tells that his Empire extended to the Ocean Sea, and that he consulted with Seraphis. The two spellings are one man.", "him"],
  serapis: ["Serapis", "Serapis, also called Seraphis, the god with whom Thulis consulted, and vpon whom Sethon may haue called. He is named, as Nesroch was.", "him"],
  plessis: ["Plessis", "Plessis, whose worke Of the truenesse of Christian Religion giues the English of the answere which Thulis had from Seraphis.", "him"],
  sosis: ["Sosis", "Sosis, in the list of old Aegyptian Kings which Cedrenus deliuers, who followed Sol the sonne of Vulcan. The length of his raigne is not set downe.", "him"],
  "sol-son-of-vulcan": ["Sol son of Vulcan", "Sol, the sonne of Vulcan, who raigned in Aegypt twentie yeeres and a halfe, in the list which Cedrenus deliuers. The one-word title would not say which Sol, so the title is four words.", "him"],
  narecho: ["Narecho", "Narecho, the name which Cedrenus giues to that Pharao who held the Crowne fiftie yeeres, and from whom the surname of Pharao passed to a long posteritie. Pharao is kept on his owne record.", "him"],
  chabreus: ["Chabreus", "Chabreus, whom Diodore, rather than Cephrenes, makes the successor of Chemmis. Herodotus his Cheops might bee this man. The two names are kept apart.", "him"],
  marus: ["Marus", "Marus, also called Menides, whom Diodorus makes the builder of the Labyrinth, fiue generations before Proteus. Reineccius takes him for Annemenes. Raleigh doth not, and coniectures that he was one of the twelue Princes.", "him"],
  chaeremon: ["Chaeremon", "Chaeremon, named with Manethon among those whose fabulous relations of Amenophis are found in Iosephus.", "him"],
  tartan: ["Tartan", "Tartan, a Captaine of Senacherib, who wonne Azotus, which Psammiticus afterwards besieged.", "him"],
  bellarmine: ["Bellarmine", "Bellarmine, the Cardinall, who thinkes that Manasses was taken in the fifteenth yeere of his raigne, and who placeth the storie of Iudith in this age. Raleigh doth not follow him.", "him"],
  "rabbi-kimhi": ["Rabbi Kimhi", "Rabbi Kimhi, also printed Kimbi, who vpon Ezekiel saith that Manasses was fortie yeeres an Idolater, and liued fifteene yeeres after his repentance. He is not Rabbi Moses Kimchi.", "him"],
  polychares: ["Polychares", "Polychares, a Messenian, who slew many Lacedaemonians after Euaephnes had slaine his Sonne. The Sonnes name is not printed.", "him"],
  euaephnes: ["Euaephnes", "Euaephnes, a Lacedaemonian, who sold the Cattaile of Polychares and slew his Sonne.", "him"],
  euphaes: ["Euphaes", "Euphaes, King of the Messenians, slaine in the first Messenian Warre. Aristodemus was chosen in his stead.", "him"],
  "aristodemus-of-messene": ["Aristodemus of Messene", "Aristodemus, chosen King of the Messenians after Euphaes, who offered his owne Daughter and afterwards slew himselfe. He is not Aristodemus vnder whom the Heraclidae returned. The one-word title would fold onto aristodemus, so the title is three words.", "him"],
  aepytus: ["Aepytus", "Aepytus, also printed Aegytus, of whose stock the Messenians were told to sacrifice a Virgin, and of whose house Aristomenes was. The two spellings are one man.", "him"],
  lyciscus: ["Lyciscus", "Lyciscus, whose Daughter the lot named for that sacrifice. He fled with her into Sparta. Her name is not printed.", "him"],
  aristomenes: ["Aristomenes", "Aristomenes, a noble Gentleman of the house of Aepytus, Generall of the Messenians in the second Warre, who died at Rhodes.", "him"],
  tyrtaeus: ["Tyrtaeus", "Tyrtaeus, a Poet, whom by appointment of an Oracle the Lacedaemonians had gotten to direct them.", "him"],
  aristocrates: ["Aristocrates", "Aristocrates, King of Arcadia, who being corrupted with mony fled from the battaile, and was stoned by the Arcadians.", "him"],
  emperamus: ["Emperamus", "Emperamus, who commanded in the Kings absence, when the slaue brought the newes that opened Era.", "him"],
  anaxander: ["Anaxander", "Anaxander, King of Sparta, to whom Aristocrates sent word of Aristomenes his march.", "him"],
  gorgus: ["Gorgus", "Gorgus, the sonne of Aristomenes, to whom, with other Gouernours, he committed his people.", "him"],
  demagetus: ["Demagetus", "Demagetus, who raigned in the Ile of Rhodes, and by an Oracle tooke to wife a daughter of Aristomenes. Her name is not printed.", "him"],
  epaminondas: ["Epaminondas", "Epaminondas, who hauing tamed the Lacedaemonians, reuoked the Messenians home and holpe them to build Messene.", "him"],
  "arphaxad-of-judith": ["Arphaxad of Iudith", "Arphaxad, the King mentioned in the Booke of Iudith, whom some would make Deioces the Mede. He is not Arphaxad the sonne of Sem. Torniellus his Arphaxad is called a fantasie, and was not made another man. The one-word title would fold onto arphaxad, so the title is three words.", "him"],
  "ioacim-high-priest": ["Ioacim the High Priest", "Ioacim, the High Priest, whom the storie of Iudith requireth. He is not Iehoiakim King of Iuda. The one-word title would not say which man, so the title is four words.", "him"],
  egeria: ["Egeria", "Egeria, a Nymph, with whom Numa perswaded the Romans that he had familiaritie, and who taught him the Ceremonies which he deliuered.", "her"],
  pompo: ["Pompo", "Pompo, the father of Numa Pompilius, named in the inscription of his graue.", "him"],
  petilius: ["L. Petilius", "L. Petilius, a Scribe, in whose ground the graue of Numa was opened by chance.", "him"],
  hippomenes: ["Hippomenes", "Hippomenes, an Athenian Gouernour, whose seuenth yeere was current with the first of Manasses.", "him"],
  leocrates: ["Leocrates", "Leocrates, one of the three last Gouernours for tenne yeeres at Athens, in the time of Manasses. Of him Raleigh findes onely the name.", "him"],
  apsander: ["Apsander", "Apsander, one of those three Gouernours. Of him Raleigh findes onely the name.", "him"],
  erixias: ["Erixias", "Erixias, also printed Erizias, the last of those three Gouernours. After him yeerely Rulers were elected. The two spellings are one man.", "him"],
  "midas-of-manasses": ["Midas in Manasses his time", "Midas, who in the raigne of Manasses held the Kingdome of Phrygia, and of whom the Poets fained Asses eares and the gift of Bacchus. He is not the Midas who was contemporary with Barac and Debora. The one-word title would fold onto midas, so the title is four words.", "him"],
  antimachus: ["Antimachus", "Antimachus, who, as Plutarch saith in the life of Romulus, obserued the Moones Eclipse at the foundation of Rome.", "him"],
  archias: ["Archias", "Archias, a Corinthian, who with Miscellus founded Syracusae in Sicily.", "him"],
  miscellus: ["Miscellus", "Miscellus, the companion of Archias, who founded Croton, and is named at the founding of Syracusae.", "him"],
  zipartes: ["Zipartes", "Zipartes, a natiue of Thrace, who in this age enlarged and beautified Nicomedia, sometime Astacus.", "him"],
  "sybilla-of-samus": ["Sybilla of Samus", "Sybilla of Samus, who according to Pausanias liued about this time. She is not the Sybilla who witnesseth of Titan and Saturne. The one-word title would fold onto sibyl, so the title is three words.", "her"],
  phalantus: ["Phalantus", "Phalantus, who conducted the Parthenians into Italie, where it is said they founded Tarentum. The Parthenians were not split into men.", "him"],
  helkiah: ["Helkiah","Helkiah the Priest, who found the Booke of Moses, and was sent with others to aske counsell of Huldah.","him"],
  huldah: ["Huldah","Huldah, or Olda, the Prophetesse, who answered the messengers of Iosias concerning the Booke of the Law.","her"],
  dioclesian: ["Dioclesian","Dioclesian, whom Ammianus Marcellinus saith fortified the passages of Euphrates. He is not Diocles, whom Iosephus cites on the siege of Tyre.","him"],
  "vasco-de-gama": ["Vasco de Gama","Vasco de Gama the Portingall, who found the Cape of good hope, following a course contrarie to the Phoenicians. He is not Steaen Gama.","him"],
  eustathius: ["Eustathius","Eustathius, who proued that Homer disgraced the Cimmerians because they had wasted his Countrie.","him"],
  marius: ["Marius the Roman","Marius the Roman, who ouerthrew the Cimbri when they descended into Italie. He is not Marius Niger. The one-word title would not say which man, so the title is three words.","him"],
  "doctor-fletcher": ["Doctor Fletcher","Doctor Fletcher, whose discourse of the Russe Common-wealth tells how the returning Scythians, or Sarmatians, recouered their homes from their bondslaues.","him"],
  "ancus-martius": ["Ancus Martius","Ancus Martius, who succeeded Tullus Hostilius in the one and twentieth yeere of Iosias. His sonnes are unnamed.","him"],
  "tarquinius-priscus": ["L. Tarquinius Priscus","L. Tarquinius Priscus, a new-come stranger, who got the Kingdome of Rome from the sonnes of Ancus, ouer whom he was Tutor. He is not Tarquinius Superbus, who stays on tarquin.","him"],
  periander: ["Periander","Periander, sonne of Cypselus, one of the seuen Sages, and a cruell Tyrant of Corinth. His wife is unnamed. The seuen Sages were not split.","him"],
  zaleucus: ["Zaleucus","Zaleucus, a Lawgiuer in Italie, whose Lawes were very milde. The people among whom he gaue them is a gap. His sonne is unnamed.","him"],
  "draco-the-lawgiver": ["Draco the Lawgiuer","Draco the Lawgiuer of Athens, who was said to haue written his Lawes with bloud, after which power was giuen to Solon. He is not Draco of Thebes. The one-word title would fold onto draco-of-thebes, so the title is three words.","him"],
  "ananias-companion-of-daniel": ["Ananias companion of Daniel","Ananias, taken with Daniel, Misael, and Azarias for a pledge, when Nabuchodonosor forced Ierusalem in the third yeere of Iehoiakim. He is not Ananias the false Prophet.","him"],
  misael: ["Misael","Misael, taken with Daniel, Ananias, and Azarias for a pledge in the third yeere of Iehoiakim.","him"],
  "azarias-companion-of-daniel": ["Azarias companion of Daniel","Azarias, taken with Daniel for a pledge in the third yeere of Iehoiakim. He is not Azaria the Priest. The one-word title would fold onto that Azarias, so the title is three words.","him"],
  "ananias-the-false-prophet": ["Ananias the false Prophet","Ananias the false Prophet, who brake the woodden Chaine which Ieremie ware, and died in the second moneth. He is not the Ananias taken with Daniel.","him"],
  iosedech: ["Iosedech","Iosedech the high Priest, sent Prisoner to Babylon with Iechonias, Ezekiel, and Mardochaeus.","him"],
  mardochaeus: ["Mardochaeus","Mardochaeus, carried to Babylon with Iechonias, Ezekiel, and Iosedech.","him"],
  sheraia: ["Sheraia","Sheraia, to whom Ieremie gaue the Booke of the euill that should fall vpon Babylon, when he went with Zedechias.","him"],
  nabuzaradan: ["Nabuzaradan","Nabuzaradan, Generall of the Armie, who burnt the Kings Palace, the Citie, and the Temple.","him"],
  saphan: ["Saphan","Saphan, whom Iosias employed in the reformation of Religion. The nephew who was made Gouernour is a gap in the print, and was not filled.","him"],
  iohanan: ["Iohanan","Iohanan, one of the Leaders of the few remayning Iewes, who discouered vnto Godoliah the intent of Ismael.","him"],
  wolphius: ["Wolphius","Wolphius, who termeth the flight of Zedechias wofull, shamefull, and vnfortunate.","him"],
};

